#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    string s;
    cin >> s;

    int i = 0;
    int j = s.length() - 1;
    string answer = "yes";
    while (i < j) {
        if (s[i] != s[j]) {
            answer = "no";
            break;
        }
        i++;
        j--;
    }
    cout << answer << endl;

    return 0;
}

code.java:
import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String s = sc.next();

        int i = 0;
        int j = s.length() - 1;
        String answer = "yes";
        while (i < j) {
            if (s.charAt(i) != s.charAt(j)) {
                answer = "no";
                break;
            }
            i++;
            j--;
        }
        System.out.println(answer);
    }
}
